const cfg = $('Configuração').first().json;
const helpers = this.helpers;
const headers = { 'X-API-KEY': cfg.unipile_key, accept: 'application/json' };
async function get(path, qs = {}) {
  return await helpers.httpRequest({ method: 'GET', url: cfg.unipile_dsn + path, qs: { account_id: cfg.unipile_account_id, ...qs }, headers, json: true, timeout: 60000 });
}
const erros = [];
const paginas = [];
const out = [];
const vistos = new Set();
function pick(p, origem) {
  const att = Array.isArray(p.attachments) ? p.attachments.map(a => ({ type: a.type, url: a.url || a.src || null, mimetype: a.mimetype || null, file_name: a.file_name || null })) : [];
  return { origem, id: p.id || null, social_id: p.social_id || null, share_url: p.share_url || null, data: p.parsed_datetime || p.date || null, texto: p.text || '', reacoes: p.reaction_counter ?? null, comentarios: p.comment_counter ?? null, compartilhamentos: p.repost_counter ?? null, impressoes: p.impressions_counter ?? null, is_repost: !!(p.is_repost || p.reposted_by), autor: p.author ? (p.author.name || p.author.public_identifier || null) : null, anexos: att };
}
async function listar(identifier, origem, isCompany, limit) {
  let cursor = null; let pages = 0;
  do {
    const qs = { limit };
    if (cursor) qs.cursor = cursor;
    if (isCompany) qs.is_company = 'true';
    let r;
    try { r = await get('/api/v1/users/' + encodeURIComponent(identifier) + '/posts', qs); }
    catch (e) { erros.push(origem + ' página ' + (pages + 1) + ': ' + e.message); break; }
    const items = r.items || [];
    paginas.push(origem + ' p' + (pages + 1) + ': ' + items.length + ' itens, cursor=' + (r.cursor ? 'sim' : 'não'));
    for (const p of items) { const k = origem + ':' + (p.social_id || p.id); if (vistos.has(k)) continue; vistos.add(k); out.push(pick(p, origem)); }
    cursor = r.cursor || null; pages++;
  } while (cursor && pages < 60);
}
let me = null;
try { me = await get('/api/v1/users/me'); } catch (e) { erros.push('perfil: ' + e.message); }
if (me && me.provider_id) await listar(me.provider_id, 'perfil_lucas', false, 50);
let empresa = null;
try { empresa = await get('/api/v1/linkedin/company/' + encodeURIComponent(cfg.empresa_linkedin)); } catch (e) { erros.push('empresa: ' + e.message); }
if (empresa && empresa.id) await listar(empresa.id, 'pagina_mia', true, 50);
const resumo = { tipo: 'resumo', perfil: me ? (me.name || ((me.first_name || '') + ' ' + (me.last_name || ''))) : null, perfil_id: me ? me.provider_id : null, empresa: empresa ? empresa.name : null, empresa_id: empresa ? empresa.id : null, posts_perfil: out.filter(o => o.origem === 'perfil_lucas').length, posts_empresa: out.filter(o => o.origem === 'pagina_mia').length, reposts_perfil: out.filter(o => o.origem === 'perfil_lucas' && o.is_repost).length, mais_antigo: out.map(o => o.data).filter(Boolean).sort()[0] || null, paginas, erros };
return [{ json: resumo }, ...out.map(o => ({ json: { tipo: 'post', ...o } }))];
